use core::sync::atomic::{AtomicU32 as A,Ordering as O};const STRONG:fn(&A,u32,u32,O,O)->Result<u32,u32>=A::compare_exchange;const WEAK:fn(&A,u32,u32,O,O)->Result<u32,u32>=A::compare_exchange_weak;fn main(){let a=A::new(7);match STRONG(&a,7,9,O::Relaxed,O::SeqCst){Ok(x)=>check(x==7),Err(_)=>check(false)}match WEAK(&a,0,13,O::Release,O::Acquire){Ok(_)=>check(false),Err(x)=>check(x==9)}check(a.load(O::SeqCst)==9);}
